theory:
**Паттерн сброса длины среза (Zero-Allocation Slice Reset):**
- Синтаксис `(*s)[:0]` обнуляет длину (`len = 0`), но сохраняет выделенную емкость (`cap`);
- Передача `*[]int` гарантирует, что вызывающий код увидит изменение `len = 0` оригинального среза;
- Позволяет повторно использовать буфер без аллокаций памяти.

code_blocks.code:
package main

import "fmt"

func ClearSlice(s *[]int) {
	if s == nil {
		return
	}
	*s = (*s)[:0] // Сброс длины до 0 с сохранением базового массива и cap!
}

func main() {
	buffer := make([]int, 5, 10)
	for i := range buffer {
		buffer[i] = i * 10
	}

	fmt.Printf("До очистки:    %v | len=%d, cap=%d\n", buffer, len(buffer), cap(buffer))

	ClearSlice(&buffer)

	fmt.Printf("После очистки: %v | len=%d, cap=%d (БУФЕР СОХРАНЕН!)\n",
		buffer, len(buffer), cap(buffer))
}

theory:
**Escape-анализ (Escape Analysis) в компиляторе Go:**
- В C/C++ возврат указателя на локальную переменную стека приводит к **висячему указателю (Dangling Pointer)** и крашу `Segmentation Fault`;
- Компилятор Go анализирует граф потока данных: если переменная «убегает» (escapes) за пределы функции, она **автоматически аллоцируется в куче (Heap)**;
- Это гарантирует 100% безопасность памяти (Memory Safety).

code_blocks.code:
package main

import "fmt"

func NewCounter() *int {
	count := 100 // Локальная переменная
	return &count // В C это привело бы к Undefined Behavior, но в Go это БЕЗОПАСНО!
}

func main() {
	ptr := NewCounter()
	fmt.Printf("Значение из кучи: %d (адрес: %p)\n", *ptr, ptr)

	*ptr += 50
	fmt.Printf("После инкремента: %d\n", *ptr)
}

package main

import "fmt"

type Person struct {
	Name string
}

func main() {
	// Для примитивных типов:
	pInt := new(int)
	*pInt = 42

	// Для структур:
	pPerson := &Person{Name: "Илья"}

	fmt.Printf("pInt:    %T -> %d\n", pInt, *pInt)
	fmt.Printf("pPerson: %T -> %+v\n", pPerson, *pPerson)
}

go run main.go
# pInt:    *int -> 42
# pPerson: *main.Person -> {Name:Илья}

theory:
**Nil Pointer Dereference:**
- Неинициализированный указатель имеет значение `nil` (адрес `0x0`);
- Попытка чтения или записи по `nil`-указателю вызывает исключение защиты памяти процессора (Page Fault), которое рантайм Go преобразует в панику.

code_blocks.code:
package main

import "fmt"

type User struct {
	Name string
}

func main() {
	var u *User // nil-указатель

	fmt.Printf("Состояние u: %v (isNil = %t)\n", u, u == nil)

	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Printf("⚠️ Перехвачена паника: %v\n", r)
			}
		}()

		// Разыменование nil приводит к панике:
		fmt.Println(u.Name)
	}()
}

theory:
**Двойной указатель `**T` (Pointer to Pointer):**
- Позволяет функции изменить **сам адрес**, на который указывает внешний указатель `*T`;
- Применяется в низкоуровневых структурах данных и CGo.

code_blocks.code:
package main

import "fmt"

func Allocate(pp **int, val int) {
	*pp = new(int) // Перенаправляем внешний указатель на новый адрес памяти
	**pp = val     // Записываем значение по новому адресу
}

func main() {
	var ptr *int // Изначально nil

	fmt.Printf("1. До Allocate:  ptr = %v\n", ptr)

	Allocate(&ptr, 42)

	fmt.Printf("2. После Allocate: ptr = %p -> значение = %d\n", ptr, *ptr)
}

package main

import "fmt"

func Redirect(target **int, newTarget *int) {
	*target = newTarget // Меняем адрес в оригинальном указателе
}

func main() {
	a, b := 10, 20
	ptr := &a

	fmt.Printf("1. ptr указывает на a: *ptr = %d (адрес: %p)\n", *ptr, ptr)

	Redirect(&ptr, &b)

	fmt.Printf("2. ptr указывает на b: *ptr = %d (адрес: %p)\n", *ptr, ptr)
}

package main

import "fmt"

func SafeDereference() {
	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("🛡️ Паника перехвачена: %v\n", r)
		}
	}()

	var p *int
	*p = 5 // Краш!
}

func main() {
	SafeDereference()
	fmt.Println("Программа стабильна")
}

