theory:
**Паттерн Nil-Safe Value Helper:**
- Часто применяется при парсинге JSON/Protobuf/GraphQL;
- Возвращает значение по указателю или дефолтное значение (Zero Value), если указатель равен `nil`.

code_blocks.code:
package main

import "fmt"

func ValueOrDefault[T any](ptr *T, def T) T {
	if ptr == nil {
		return def
	}
	return *ptr
}

func main() {
	var nilScore *int
	validScore := 85

	fmt.Printf("1. nilScore:   %d (дефолт)\n", ValueOrDefault(nilScore, 0))
	fmt.Printf("2. validScore: %d\n", ValueOrDefault(&validScore, 0))
}

theory:
**Классический баг сохранения `&v` в `for range` (до Go 1.22):**
- Переменная `v` в цикле `for _, v := range items` переиспользовалась;
- Сохранение `&v` приводило к тому, что все элементы среза указателей ссылались на один и тот же адрес с последним значением;
- В Go 1.22+ скоуп `v` изолирован, но паттерн явного взятия адреса элемента среза `&items[i]` является эталоном безопасности для всех версий Go.

code_blocks.code:
package main

import "fmt"

func main() {
	numbers := []int{10, 20, 30}
	var pointers []*int

	// ЭТАЛОННЫЙ СПОСОБ: берем адрес элемента напрямую из среза:
	for i := range numbers {
		pointers = append(pointers, &numbers[i])
	}

	fmt.Println("Значения по сохраненным указателям:")
	for idx, ptr := range pointers {
		fmt.Printf("  pointers[%d] = %d (адрес: %p)\n", idx, *ptr, ptr)
	}
}

package main

import "fmt"

func main() {
	x := 42
	fmt.Printf("Значение: %d | Адрес в памяти: %p\n", x, &x)
}

theory:
**Строгая типизация указателей в Go:**
- Указатели на разные типы (`*int` и `*string`) являются **несовместимыми типами**;
- Нельзя присвоить `*int` переменной типа `*string` без `unsafe.Pointer`.

code_blocks.code:
package main

import "fmt"

func Swap(a, b *int) {
	if a == nil || b == nil {
		return
	}
	*a, *b = *b, *a // Множественное присваивание в Go
}

func main() {
	x, y := 100, 200
	fmt.Printf("До Swap:    x = %d, y = %d\n", x, y)

	Swap(&x, &y)

	fmt.Printf("После Swap: x = %d, y = %d\n", x, y)
}

package main

import "fmt"

func swap(a, b *int) {
	*a, *b = *b, *a
}

func main() {
	// 1. Локальный swap без функций:
	a, b := 1, 2
	a, b = b, a
	fmt.Printf("Локальный swap: a=%d, b=%d\n", a, b)

	// 2. Через функцию и указатели:
	swap(&a, &b)
	fmt.Printf("Через swap(&a, &b): a=%d, b=%d\n", a, b)
}

theory:
**Value Semantics vs Pointer Semantics:**
- `MoveByValue`: функциональный стиль (чистая функция, иммутабельность, потокобезопасность);
- `MoveByPointer`: императивный стиль (мутация по месту, отсутствие дополнительных аллокаций).

code_blocks.code:
package main

import "fmt"

type Point struct {
	X, Y int
}

func MoveByValue(p Point, dx, dy int) Point {
	p.X += dx
	p.Y += dy
	return p // Возвращает новую независимую копию
}

func MoveByPointer(p *Point, dx, dy int) {
	if p == nil {
		return
	}
	p.X += dx
	p.Y += dy // Изменяет исходный объект
}

func main() {
	p1 := Point{X: 10, Y: 20}
	p2 := MoveByValue(p1, 5, 5)

	fmt.Printf("1. Value подход:   Оригинал p1=%+v | Новый p2=%+v\n", p1, p2)

	MoveByPointer(&p1, 5, 5)
	fmt.Printf("2. Pointer подход: Оригинал p1=%+v (ИЗМЕНЕН НА МЕСТЕ!)\n", p1)
}

go run main.go
# 1. Value подход:   Оригинал p1={X:10 Y:20} | Новый p2={X:15 Y:25}
# 2. Pointer подход: Оригинал p1={X:15 Y:25} (ИЗМЕНЕН НА МЕСТЕ!)

theory:
**Указатель на структуру SliceHeader `*[]T`:**
- При реаллокации среза функция `append` создает новый массив и возвращает новый `SliceHeader`;
- Передача указателя `*[]int` позволяет функции перезаписать заголовок среза вызывающей стороны `*s = append(*s, val)`.

code_blocks.code:
package main

import "fmt"

func AppendWithPointer(s *[]int, val int) {
	if s == nil {
		return
	}
	*s = append(*s, val)
}

func main() {
	var nums []int // nil-срез
	fmt.Printf("1. До:    %v | len=%d, cap=%d\n", nums, len(nums), cap(nums))

	AppendWithPointer(&nums, 10)
	AppendWithPointer(&nums, 20)
	AppendWithPointer(&nums, 30)

	fmt.Printf("2. После: %v | len=%d, cap=%d (МУТАЦИЯ СОХРАНЕНА!)\n",
		nums, len(nums), cap(nums))
}

package main

import "fmt"

func SwapValues(a, b *int) {
	if a == nil || b == nil {
		return
	}
	*a, *b = *b, *a
}

func main() {
	first, second := 50, 90
	fmt.Printf("До:    first = %d, second = %d\n", first, second)

	SwapValues(&first, &second)

	fmt.Printf("После: first = %d, second = %d\n", first, second)
}

